def icon_ico_bytes():
    return base64.b64decode(ICON_ICO_B64)


_ICON_TMP = []


def set_app_icon(win):
    """Pone el ícono incrustado en la ventana y en la barra de tareas."""
    try:                                   # Windows: identidad propia para que la barra use nuestro ícono
        if sys.platform == "win32":
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("BT3.EffectStudio.App")
    except Exception:
        pass
    try:                                   # multiplataforma, sin archivos
        img = tk.PhotoImage(data=ICON_PNG_B64.replace("\n", ""))
        win.iconphoto(True, img)
        win._icon_ref = img
    except Exception:
        pass
    if sys.platform == "win32":            # .ico real para la barra de título (todos los tamaños)
        try:
            import tempfile
            fd, path = tempfile.mkstemp(suffix=".ico", prefix="bt3es_")
            with os.fdopen(fd, "wb") as fh:
                fh.write(icon_ico_bytes())
            win.iconbitmap(default=path)
            _ICON_TMP.append(path)
            import atexit
            atexit.register(lambda p=path: os.path.exists(p) and os.remove(p))
        except Exception:
            pass


